def has_close_elements(numbers, threshold):
    for i in range(len(numbers) - 1):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    current_group = ""
    groups = []

    for char in paren_string:
        if char == '(':
            stack.append(char)
            current_group += char
        elif char == ')':
            stack.pop()
            current_group += char
            if not stack:
                groups.append(current_group[1:])
                current_group = ""
        else:
            current_group += char

    if stack:
        raise ValueError("Input string has unbalanced parentheses")

    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    deviation = [abs(x - mean) for x in numbers]
    return sum(deviation) / len(deviation)

def max_value_on_paths(N, grid_values):
    # Initialize the dp table with all zeros
    dp = [[0] * N for _ in range(N)]

    # Loop through the grid values and populate the dp table
    for x, y, value in grid_values:
        dp[x][y] = value

    # Loop through the dp table and calculate the maximum sum of values on two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            max_sum = max(max_sum, dp[i][j] + dp[i+1][j] + dp[i][j+1] + dp[i+1][j+1])

    return max_sum

def find_number_combinations():

    combinations = []
    for i in range(1, 10):
        for j in range(i, 10):
            if j * 2 == i:
                for k in range(i, 10):
                    if k * 3 == i:
                        combinations.append((i, j * 2, k * 3))
    return sorted(combinations)

def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("Input out of range")
    result = 0
    for i in range(1, n+1):
        result += i * factorial(i-1)
    return result

def factorial(n: int) -> int:
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

