def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13:
        return "Invalid ISBN length"
    if not isbn.isdigit():
        return "Invalid ISBN characters"
    checksum = int(isbn[-1])
    isbn_digits = [int(digit) for digit in isbn[:-1]]
    sum_of_squares = 0
    for i, digit in enumerate(isbn_digits):
        sum_of_squares += (i + 1) * digit
    if sum_of_squares % 11 == 0:
        if checksum == 0:
            return "Right"
        else:
            isbn = isbn[:-1] + str(checksum)
            return isbn
    else:
        checksum = 11 - (sum_of_squares % 11)
        isbn = isbn[:-1] + str(checksum)
        return isbn

def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix with M rows and N columns
    matrix = [[0] * N for _ in range(M)]

    # Iterate over the chatting pairs and increment the count in the matrix
    for (Xi, Yi), (Pi, Qi) in chatting_pairs:
        matrix[Xi][Yi] += 1

    # Initialize the best row and column indices
    best_row = 0
    best_col = 0

    # Iterate over the rows and columns
    for i in range(M):
        for j in range(N):
            # If the current position is occupied, skip it
            if matrix[i][j] == 0:
                continue

            # Calculate the count of chatting pairs that can be separated by adding an aisle in this position
            count = 0
            for k in range(max(0, i - K), min(M, i + K + 1)):
                for l in range(max(0, j - L), min(N, j + L + 1)):
                    if matrix[k][l] > 0:
                        count += 1

            # If the count is higher than the current best, update the best row and column indices
            if count > D:
                best_row = i
                best_col = j
                D = count

    return f"{best_row}", f"{best_col} {best_row}"

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]):
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            price, importance = items[i - 1]
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)
    return dp[-1][-1]

def polynomial_to_string(n, coeffs):
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for deg, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        term = ''
        if coeff < 0:
            term += '-'
        if coeff != 1 or deg == 0:
            term += f'{abs(coeff)}'
        if deg > 0:
            term += f'x^{deg}'
        else:
            term += 'x'
        terms.append(term)
    return '+'.join(terms)

def largest_prime_factor(n: int) -> int:
    # check if 'n' is a prime number
    if n == 2 or n == 3:
        return n

    # iterate from 2 to sqrt(n) and check if a factor exists
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return n // i

    # no factors found, so 'n' is a prime number
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    dp = [0] * (n+1)
    dp[0] = 1

    for i in range(1, k+1):
        for j in range(i, n+1):
            if j-i >= x:
                dp[j] += dp[j-i]

    return dp[n]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    count = 1
    for i in range(1, int(last / 2) + 1):
        if n + i in memo:
            count += memo[n + i]
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // x0 // a
        if gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

def gcd(a, b):
    while b != 0:
        a, b = b, a % b

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.
    """

    # Create a dictionary to map each inorder node to its index in the postorder traversal
    inorder_to_postorder = {}
    for i, node in enumerate(postorder):
        inorder_to_postorder[inorder[i]] = i

    # Create a stack to keep track of the nodes in the preorder traversal
    stack = []

    # Iterate through the postorder traversal and fill in the preorder traversal
    for node in postorder:
        if node not in inorder_to_postorder:
            # This is an internal node, add it to the stack
            stack.append(node)
        else:
            # This is a leaf node, pop the stack until we reach the parent node
            while stack and stack[-1] not in inorder_to_postorder[node]:
                stack.pop()
            # Add the node to the preorder traversal
            stack.append(node)

    # Return the preorder traversal as a string
    return "".join(stack)

