def calculate_arrangements(n, m, a):
    # Initialize the dp array
    dp = [0] * (m + 1)
    dp[0] = 1

    # Loop through each type of flower
    for i in range(1, n + 1):
        # Loop through each pot for the current flower
        for j in range(1, m + 1):
            # Check if the current pot can hold the current flower
            if j - 1 >= a[i - 1]:
                dp[j] = (dp[j] + dp[j - a[i - 1]]) % 1000000

    return dp[m]

def next_permutation(perm: list) -> bool:
    i = len(perm) - 1
    while i > 0 and perm[i - 1] >= perm[i]:
        i -= 1
    if i == 0 and perm[i] >= perm[i + 1]:
        return False
    j = len(perm) - 1
    while perm[j] <= perm[i - 1]:
        j -= 1
    perm[i - 1], perm[j] = perm[j], perm[i - 1]
    perm[i:] = perm[i:][::-1]
    return True

def min_groups(w, n, prices):
    dp = [[0] * (n+1) for _ in range(w+1)]
    for i in range(1, n+1):
        for j in range(1, w+1):
            if prices[i-1] > j:
                dp[j][i] = dp[j][i-1]
            else:
                dp[j][i] = max(dp[j][i-1], 1 + dp[j-prices[i-1]][i-1])
    return dp[w][n]

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        # Use the recurrence relation to compute the number of moves for n pairs of discs
        moves = 2 * (4**(n-1)) - 1
        # Add the number of moves for n-1 pairs of discs on the B pole
        moves += hanoi_double_iterative(n-1)
        return moves

